import{_t as e,it as t,n,rt as r}from"./chunks/framework.CfRzmOnu.js";var i=JSON.parse(`{"title":"Error Codes","description":"","frontmatter":{"outline":[2,3],"packageVersion":"0.16.0"},"headers":[],"relativePath":"reference/errors.md","filePath":"site/reference/errors.md","lastUpdated":1792852428000}`),a={name:`reference/errors.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="error-codes" tabindex="-1">Error Codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to “Error Codes”">​</a></h1><p>Every expected failure in micro509 carries a machine-readable code. <code>Result</code>-returning APIs put it on <code>result.error.code</code> (or <code>result.code</code> on flattened failures); builder APIs that take developer-supplied config throw a coded error that <code>isResultError</code> detects and <code>error.code</code> discriminates.</p><p>This page lists <strong>every</strong> public error-code union and its members, grouped by the entrypoint that owns it. A repo test extracts these unions from the type declarations and fails when this page and the exported types disagree, in either direction.</p><div class="info custom-block"><p class="custom-block-title">Stability</p><p>Unions may gain members in minor releases; treat them as non-exhaustive and keep a <code>default</code> branch. Renaming or removing a code only happens in a major release.</p></div><h2 id="micro509-x509" tabindex="-1">micro509/x509 <a class="header-anchor" href="#micro509-x509" aria-label="Permalink to “micro509/x509”">​</a></h2><h3 id="parsecertificateerrorcode" tabindex="-1">ParseCertificateErrorCode <a class="header-anchor" href="#parsecertificateerrorcode" aria-label="Permalink to “ParseCertificateErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>limit_exceeded</code></td><td>A micro509 limit: an OBJECT IDENTIFIER sub-identifier encoded in more than 64 octets, a tag number of 2^53 or more, or DER nested deeper than 64 levels</td></tr><tr><td><code>malformed</code></td><td>Input is not a valid DER or PEM X.509 certificate</td></tr><tr><td><code>unsupported</code></td><td>A TeletexString name value holds an octet outside the X.690 §8.23.5.2 initial state, which micro509 does not decode</td></tr></tbody></table><h3 id="parsecertificatesigningrequesterrorcode" tabindex="-1">ParseCertificateSigningRequestErrorCode <a class="header-anchor" href="#parsecertificatesigningrequesterrorcode" aria-label="Permalink to “ParseCertificateSigningRequestErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>limit_exceeded</code></td><td>A micro509 limit: an OBJECT IDENTIFIER sub-identifier encoded in more than 64 octets, a tag number of 2^53 or more, or DER nested deeper than 64 levels</td></tr><tr><td><code>malformed</code></td><td>Input is not a valid DER or PEM PKCS#10 request</td></tr><tr><td><code>unsupported</code></td><td>A TeletexString name value holds an octet outside the X.690 §8.23.5.2 initial state, which micro509 does not decode</td></tr></tbody></table><h3 id="matchcertificateprivatekeyerrorcode" tabindex="-1">MatchCertificatePrivateKeyErrorCode <a class="header-anchor" href="#matchcertificateprivatekeyerrorcode" aria-label="Permalink to “MatchCertificatePrivateKeyErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>key_mismatch</code></td><td>Right algorithm, different key</td></tr><tr><td><code>key_type_mismatch</code></td><td>Private key algorithm differs from the SPKI&#39;s</td></tr><tr><td><code>limit_exceeded</code></td><td>Certificate exceeds a micro509 decoding limit, see <code>ParseCertificateErrorCode</code></td></tr><tr><td><code>malformed_certificate</code></td><td>Certificate source failed to parse</td></tr><tr><td><code>unsupported</code></td><td>Certificate holds a value micro509 does not decode, see <code>ParseCertificateErrorCode</code></td></tr><tr><td><code>unsupported_private_key</code></td><td>Key type has no supported SPKI derivation</td></tr></tbody></table><h3 id="createcertificateerrorcode" tabindex="-1">CreateCertificateErrorCode <a class="header-anchor" href="#createcertificateerrorcode" aria-label="Permalink to “CreateCertificateErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>issuer_certificate_invalid</code></td><td><code>issuerCertificate</code> is not a PEM, DER or parsed certificate</td></tr><tr><td><code>issuer_distinguished_name_empty</code></td><td><a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-4.1.2.4" target="_blank" rel="noreferrer">RFC 5280 §4.1.2.4</a> requires a non-empty issuer DN</td></tr><tr><td><code>serial_number_not_positive</code></td><td>Serial must be a positive integer (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-4.1.2.2" target="_blank" rel="noreferrer">RFC 5280 §4.1.2.2</a>)</td></tr><tr><td><code>serial_number_too_long</code></td><td>Serial DER INTEGER exceeds 20 octets (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-4.1.2.2" target="_blank" rel="noreferrer">RFC 5280 §4.1.2.2</a>)</td></tr><tr><td><code>validity_date_invalid</code></td><td><code>notBefore</code>, <code>notAfter</code> or <code>days</code> gives an invalid date</td></tr><tr><td><code>validity_not_after_before_not_before</code></td><td>Validity window ends before it starts</td></tr></tbody></table><h3 id="nameencodererrorcode" tabindex="-1">NameEncoderErrorCode <a class="header-anchor" href="#nameencodererrorcode" aria-label="Permalink to “NameEncoderErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid_country_code</code></td><td>Country attribute is not exactly two letters</td></tr><tr><td><code>name_attribute_empty</code></td><td>Attribute value is empty (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#appendix-A.1" target="_blank" rel="noreferrer">RFC 5280 A.1</a> <code>SIZE (1..)</code>)</td></tr><tr><td><code>name_attribute_lone_surrogate</code></td><td>Attribute value holds a lone UTF-16 surrogate, which has no UTF-8 encoding</td></tr><tr><td><code>name_attribute_too_long</code></td><td>Attribute value exceeds its <a href="https://www.rfc-editor.org/rfc/rfc5280.html#appendix-A.1" target="_blank" rel="noreferrer">RFC 5280 A.1</a> upper bound</td></tr><tr><td><code>relative_distinguished_name_empty</code></td><td>RDN carries no attributes</td></tr><tr><td><code>unsupported_name_field</code></td><td>Attribute key is not an encodable name field</td></tr></tbody></table><h3 id="extensionencodererrorcode" tabindex="-1">ExtensionEncoderErrorCode <a class="header-anchor" href="#extensionencodererrorcode" aria-label="Permalink to “ExtensionEncoderErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>authority_info_access_empty</code></td><td>AIA input has no access descriptions</td></tr><tr><td><code>authority_info_access_ocsp_not_uri</code></td><td>An OCSP access method requires a URI location</td></tr><tr><td><code>certificate_policies_empty</code></td><td>certificatePolicies lists no policies</td></tr><tr><td><code>crl_distribution_points_empty</code></td><td>cRLDistributionPoints lists no points</td></tr><tr><td><code>directory_name_not_sequence</code></td><td>directoryName payload is not a DER SEQUENCE</td></tr><tr><td><code>display_text_control_character</code></td><td>explicitText contains a C0 or C1 control character (<a href="https://www.rfc-editor.org/rfc/rfc6818.html#section-3" target="_blank" rel="noreferrer">RFC 6818 §3</a>)</td></tr><tr><td><code>display_text_ia5_string</code></td><td>explicitText requested as IA5String (<a href="https://www.rfc-editor.org/rfc/rfc6818.html#section-3" target="_blank" rel="noreferrer">RFC 6818 §3</a>)</td></tr><tr><td><code>display_text_lone_surrogate</code></td><td>explicitText or noticeRef organization holds a lone UTF-16 surrogate</td></tr><tr><td><code>display_text_not_nfc</code></td><td>UTF8String or BMPString explicitText is not NFC (<a href="https://www.rfc-editor.org/rfc/rfc6818.html#section-3" target="_blank" rel="noreferrer">RFC 6818 §3</a>)</td></tr><tr><td><code>display_text_out_of_range</code></td><td>User-notice DisplayText length outside <a href="https://www.rfc-editor.org/rfc/rfc5280.html" target="_blank" rel="noreferrer">RFC 5280</a> bounds</td></tr><tr><td><code>distribution_point_crl_issuer_empty</code></td><td><code>cRLIssuer</code> present but holds no name</td></tr><tr><td><code>distribution_point_crl_issuer_not_directory_name</code></td><td><code>cRLIssuer</code> entries must be directoryNames (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-4.2.1.13" target="_blank" rel="noreferrer">RFC 5280 §4.2.1.13</a>)</td></tr><tr><td><code>distribution_point_empty</code></td><td>Distribution point carries no field at all</td></tr><tr><td><code>distribution_point_full_name_empty</code></td><td><code>fullName</code> present but holds no GeneralName</td></tr><tr><td><code>distribution_point_relative_name_multiple_crl_issuers</code></td><td><code>nameRelativeToCRLIssuer</code> permits at most one <code>cRLIssuer</code></td></tr><tr><td><code>domain_trailing_dot</code></td><td>A dNSName or rfc822Name domain ends in the root dot, outside the <a href="https://www.rfc-editor.org/rfc/rfc1034.html#section-3.5" target="_blank" rel="noreferrer">RFC 1034 §3.5</a> preferred name syntax (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-4.2.1.6" target="_blank" rel="noreferrer">RFC 5280 §4.2.1.6</a>)</td></tr><tr><td><code>duplicate_extension_oid</code></td><td>Same extension OID supplied twice</td></tr><tr><td><code>duplicate_policy_oid</code></td><td>Same policy OID listed twice</td></tr><tr><td><code>edwards_key_usage_forbids_agreement_bit</code></td><td>Ed25519/Ed448 keyUsage asserts an agreement or cipher bit</td></tr><tr><td><code>edwards_key_usage_forbids_key_cert_sign</code></td><td>End-entity Edwards certificate asserts <code>keyCertSign</code>/<code>cRLSign</code></td></tr><tr><td><code>edwards_key_usage_requires_key_cert_sign</code></td><td>Edwards CA keyUsage missing <code>keyCertSign</code></td></tr><tr><td><code>edwards_key_usage_requires_signing_bit</code></td><td>Edwards keyUsage missing a signing bit (<a href="https://www.rfc-editor.org/rfc/rfc9295.html#section-3" target="_blank" rel="noreferrer">RFC 9295 §3</a>)</td></tr><tr><td><code>email_name_constraint_names_mailbox</code></td><td>rfc822Name constraint names a mailbox (<a href="https://www.rfc-editor.org/rfc/rfc9549.html#section-2.2" target="_blank" rel="noreferrer">RFC 9549 §2.2</a>)</td></tr><tr><td><code>empty_general_name_value</code></td><td>dNSName/rfc822Name/URI/SRV value is empty</td></tr><tr><td><code>empty_subject_requires_subject_alt_name</code></td><td>Empty subject DN without a critical, non-empty SAN</td></tr><tr><td><code>extended_key_usage_empty</code></td><td>EKU list is empty</td></tr><tr><td><code>extension_must_be_critical</code></td><td><a href="https://www.rfc-editor.org/rfc/rfc5280.html" target="_blank" rel="noreferrer">RFC 5280</a> fixes this extension as critical</td></tr><tr><td><code>extension_must_be_non_critical</code></td><td><a href="https://www.rfc-editor.org/rfc/rfc5280.html" target="_blank" rel="noreferrer">RFC 5280</a> fixes this extension as non-critical</td></tr><tr><td><code>extension_not_supported_in_context</code></td><td>Extension not allowed in this certificate/CSR context</td></tr><tr><td><code>invalid_bmp_string</code></td><td>BMPString explicitText outside the X.680 BMPString repertoire</td></tr><tr><td><code>invalid_general_name_content</code></td><td>x400Address or ediPartyName contents fail their schema or encoding</td></tr><tr><td><code>invalid_general_name_tag</code></td><td>GeneralName tag outside the nine <a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-4.2.1.6" target="_blank" rel="noreferrer">RFC 5280 §4.2.1.6</a> alternatives</td></tr><tr><td><code>invalid_ia5_string</code></td><td>Non-ASCII input for an IA5String value</td></tr><tr><td><code>invalid_idn</code></td><td>Domain name is not valid IDNA2008 (<a href="https://www.rfc-editor.org/rfc/rfc5891.html#section-4" target="_blank" rel="noreferrer">RFC 5891 §4</a>)</td></tr><tr><td><code>invalid_ip_name_constraint</code></td><td>IP constraint bytes are not address+mask of one family</td></tr><tr><td><code>invalid_krb5_principal_name</code></td><td>KRB5PrincipalName realm holds NUL, a component is not KerberosString text, or nameType is not an Int32</td></tr><tr><td><code>invalid_other_name_value</code></td><td>otherName value is not one DER element micro509 can validate</td></tr><tr><td><code>invalid_oid</code></td><td>String is not an OID within X.660 arc bounds</td></tr><tr><td><code>invalid_smtp_utf8_mailbox</code></td><td>SmtpUTF8Mailbox malformed or domain not A-labels (<a href="https://www.rfc-editor.org/rfc/rfc9598.html#section-3" target="_blank" rel="noreferrer">RFC 9598 §3</a>)</td></tr><tr><td><code>invalid_srv_name</code></td><td>SRVName not _Service.Name with <a href="https://www.rfc-editor.org/rfc/rfc6335.html" target="_blank" rel="noreferrer">RFC 6335</a> service and LDH Name</td></tr><tr><td><code>invalid_srv_name_constraint</code></td><td>SRVName constraint not _Service.Name, _Service or Name (<a href="https://www.rfc-editor.org/rfc/rfc4985.html" target="_blank" rel="noreferrer">RFC 4985</a>)</td></tr><tr><td><code>invalid_uri_name_constraint</code></td><td>URI constraint not an FQDN or a leading-period domain (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-4.2.1.10" target="_blank" rel="noreferrer">RFC 5280 §4.2.1.10</a>)</td></tr><tr><td><code>invalid_visible_string</code></td><td>VisibleString explicitText outside printable ASCII</td></tr><tr><td><code>key_usage_empty</code></td><td>keyUsage asserts no bits</td></tr><tr><td><code>limit_exceeded</code></td><td>An OID arc encodes in more than 64 octets, or GeneralName contents nest deeper than 64 levels, a micro509 limit</td></tr><tr><td><code>malformed_known_extension_value</code></td><td><code>customExtensions</code> payload with a known OID fails to decode as it</td></tr><tr><td><code>montgomery_key_usage_forbids_both_cipher_bits</code></td><td>X25519/X448 asserts both <code>encipherOnly</code> and <code>decipherOnly</code></td></tr><tr><td><code>montgomery_key_usage_forbids_signature_bit</code></td><td>X25519/X448 asserts a signature bit (<a href="https://www.rfc-editor.org/rfc/rfc8410.html#section-12" target="_blank" rel="noreferrer">RFC 8410 §12</a>)</td></tr><tr><td><code>montgomery_key_usage_requires_key_agreement</code></td><td>X25519/X448 keyUsage missing <code>keyAgreement</code> (<a href="https://www.rfc-editor.org/rfc/rfc9295.html#section-3" target="_blank" rel="noreferrer">RFC 9295 §3</a>)</td></tr><tr><td><code>name_constraints_empty</code></td><td>nameConstraints has neither permitted nor excluded subtrees</td></tr><tr><td><code>no_rev_avail_conflict</code></td><td>noRevAvail with cA or a revocation pointer (<a href="https://www.rfc-editor.org/rfc/rfc9608.html#section-3" target="_blank" rel="noreferrer">RFC 9608 §3</a>)</td></tr><tr><td><code>other_name_type_id_has_variant</code></td><td>otherName belongs to the <code>srv</code>, <code>smtpUtf8Mailbox</code>, <code>upn</code> or <code>krb5PrincipalName</code> variant</td></tr><tr><td><code>path_length_requires_ca</code></td><td><code>pathLength</code> on a non-CA basicConstraints</td></tr><tr><td><code>path_length_requires_key_cert_sign</code></td><td><code>pathLength</code> requires keyUsage asserting <code>keyCertSign</code></td></tr><tr><td><code>policy_constraints_empty</code></td><td>policyConstraints carries neither field</td></tr><tr><td><code>policy_mappings_any_policy</code></td><td>anyPolicy may not appear in a policy mapping</td></tr><tr><td><code>policy_mappings_empty</code></td><td>Mappings list is empty</td></tr><tr><td><code>reserved_policy_qualifier_oid</code></td><td>Custom qualifier uses a reserved qualifier OID</td></tr><tr><td><code>smtp_utf8_mailbox_ascii_local_part</code></td><td>ASCII Local-part must use rfc822Name (<a href="https://www.rfc-editor.org/rfc/rfc9598.html#section-3" target="_blank" rel="noreferrer">RFC 9598 §3</a>)</td></tr></tbody></table><h2 id="micro509-verify" tabindex="-1">micro509/verify <a class="header-anchor" href="#micro509-verify" aria-label="Permalink to “micro509/verify”">​</a></h2><h3 id="verifyerrorcode" tabindex="-1">VerifyErrorCode <a class="header-anchor" href="#verifyerrorcode" aria-label="Permalink to “VerifyErrorCode”">​</a></h3><p>Meanings are tabled in the <a href="./../guide/verification#error-codes">verification guide</a>; both tables are enforced against <code>VERIFY_ERROR_CODES</code> by tests.</p><p><code>authority_key_identifier_mismatch</code>, <code>ca_required</code>, <code>certificate_expired</code>, <code>certificate_revoked</code>, <code>common_name_fallback_suppressed</code>, <code>display_text_oversized</code>, <code>ec_domain_parameters_missing</code>, <code>explicit_policy_required</code>, <code>extended_key_usage_invalid</code>, <code>initial_policy_set_not_satisfied</code>, <code>intermediate_eku_constraint</code>, <code>issuer_not_found</code>, <code>key_cert_sign_required</code>, <code>name_constraints_violated</code>, <code>no_rev_avail_conflict</code>, <code>no_trusted_root</code>, <code>public_key_distrusted</code>, <code>path_length_exceeded</code>, <code>path_building_limit_exceeded</code>, <code>revocation_indeterminate</code>, <code>self_signed_leaf_not_allowed</code>, <code>signature_invalid</code>, <code>subject_alt_name_mismatch</code>, <code>unrecognized_critical_extension</code>, <code>unsupported_initial_name_constraints</code>, <code>unsupported_name_constraints</code>, <code>unsupported_signature_algorithm_parameters</code>, <code>unsupported</code>, <code>limit_exceeded</code></p><h3 id="matchserviceidentityerrorcode" tabindex="-1">MatchServiceIdentityErrorCode <a class="header-anchor" href="#matchserviceidentityerrorcode" aria-label="Permalink to “MatchServiceIdentityErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>common_name_fallback_suppressed</code></td><td>CN match suppressed by presented identifiers</td></tr><tr><td><code>limit_exceeded</code></td><td>The certificate exceeds a micro509 decoding limit, see <code>ParseCertificateErrorCode</code></td></tr><tr><td><code>service_identity_mismatch</code></td><td>SRV-ID or URI-ID service part does not match</td></tr><tr><td><code>subject_alt_name_mismatch</code></td><td>No SAN matches the requested identity</td></tr><tr><td><code>unsupported</code></td><td>The certificate holds a value micro509 does not decode, see <code>ParseCertificateErrorCode</code></td></tr><tr><td><code>unsupported_service_identity_type</code></td><td>Identity type has no matcher</td></tr></tbody></table><h2 id="micro509-revocation" tabindex="-1">micro509/revocation <a class="header-anchor" href="#micro509-revocation" aria-label="Permalink to “micro509/revocation”">​</a></h2><h3 id="parsecertificaterevocationlisterrorcode" tabindex="-1">ParseCertificateRevocationListErrorCode <a class="header-anchor" href="#parsecertificaterevocationlisterrorcode" aria-label="Permalink to “ParseCertificateRevocationListErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>limit_exceeded</code></td><td>A micro509 limit: an OBJECT IDENTIFIER sub-identifier encoded in more than 64 octets, a tag number of 2^53 or more, or DER nested deeper than 64 levels</td></tr><tr><td><code>malformed</code></td><td>Input is not a valid DER or PEM CRL</td></tr><tr><td><code>unsupported</code></td><td>A TeletexString name value holds an octet outside the X.690 §8.23.5.2 initial state, which micro509 does not decode</td></tr></tbody></table><h3 id="parseocsprequesterrorcode" tabindex="-1">ParseOcspRequestErrorCode <a class="header-anchor" href="#parseocsprequesterrorcode" aria-label="Permalink to “ParseOcspRequestErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>limit_exceeded</code></td><td>A micro509 limit: an OBJECT IDENTIFIER sub-identifier encoded in more than 64 octets, a tag number of 2^53 or more, or DER nested deeper than 64 levels</td></tr><tr><td><code>malformed</code></td><td>Input is not a valid DER or PEM OCSP request</td></tr><tr><td><code>unsupported</code></td><td>A TeletexString name value holds an octet outside the X.690 §8.23.5.2 initial state, which micro509 does not decode</td></tr></tbody></table><h3 id="parseocspresponseerrorcode" tabindex="-1">ParseOcspResponseErrorCode <a class="header-anchor" href="#parseocspresponseerrorcode" aria-label="Permalink to “ParseOcspResponseErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>limit_exceeded</code></td><td>A micro509 limit: an OBJECT IDENTIFIER sub-identifier encoded in more than 64 octets, a tag number of 2^53 or more, or DER nested deeper than 64 levels</td></tr><tr><td><code>malformed</code></td><td>Input is not a valid DER or PEM OCSP response</td></tr><tr><td><code>unsupported</code></td><td>A TeletexString name value holds an octet outside the X.690 §8.23.5.2 initial state, which micro509 does not decode</td></tr></tbody></table><h3 id="checkcertificaterevocationagainstcrlerrorcode" tabindex="-1">CheckCertificateRevocationAgainstCrlErrorCode <a class="header-anchor" href="#checkcertificaterevocationagainstcrlerrorcode" aria-label="Permalink to “CheckCertificateRevocationAgainstCrlErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>crl_sign_not_permitted</code></td><td>CRL signer&#39;s keyUsage lacks <code>cRLSign</code>, or a v3 signer has no keyUsage</td></tr><tr><td><code>issuer_mismatch</code></td><td>CRL issuer does not match the certificate&#39;s issuer</td></tr><tr><td><code>limit_exceeded</code></td><td>A CRL or certificate exceeds a micro509 decoding limit, see <code>ParseCertificateRevocationListErrorCode</code></td></tr><tr><td><code>non_applicable</code></td><td>No supplied CRL applies to the certificate (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-6.3.3" target="_blank" rel="noreferrer">RFC 5280 §6.3.3</a>)</td></tr><tr><td><code>reason_code_unrecognized</code></td><td>The certificate&#39;s entry carries a CRLReason outside RFC 5280 §5.3.1 under <code>unrecognizedReasonCode: &#39;reject&#39;</code></td></tr><tr><td><code>signature_invalid</code></td><td>CRL signature fails against the issuer key</td></tr><tr><td><code>stale_crl</code></td><td>CRL outside its <code>thisUpdate</code>/<code>nextUpdate</code> window or older than <code>maxAgeMs</code></td></tr><tr><td><code>unsupported</code></td><td>A CRL or certificate holds a value micro509 does not decode, see <code>ParseCertificateRevocationListErrorCode</code></td></tr></tbody></table><p>A <code>non_applicable</code> failure carries a <code>reason</code>. <code>delta_crl_incompatible</code> covers a delta CRL that does not pair with the complete CRL, including one whose <code>thisUpdate</code> precedes the complete CRL&#39;s <code>thisUpdate</code>.</p><h3 id="validateocspresponseerrorcode" tabindex="-1">ValidateOcspResponseErrorCode <a class="header-anchor" href="#validateocspresponseerrorcode" aria-label="Permalink to “ValidateOcspResponseErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>issuer_mismatch</code></td><td>CertID does not hash to the supplied issuer</td></tr><tr><td><code>limit_exceeded</code></td><td>A response, request or certificate exceeds a micro509 decoding limit, see <code>ParseOcspResponseErrorCode</code></td></tr><tr><td><code>next_update_missing</code></td><td>A response omits <code>nextUpdate</code> under <code>profile: &#39;rfc9919&#39;</code> (<a href="https://www.rfc-editor.org/rfc/rfc9919.html#section-5" target="_blank" rel="noreferrer">RFC 9919 §5</a>)</td></tr><tr><td><code>nonce_mismatch</code></td><td>Response nonce differs from the request&#39;s</td></tr><tr><td><code>ocsp_signing_missing</code></td><td>Delegated responder lacks the <code>ocspSigning</code> EKU</td></tr><tr><td><code>request_mismatch</code></td><td>Response does not answer every requested CertID</td></tr><tr><td><code>responder_chain_invalid</code></td><td>Responder certificate path fails validation</td></tr><tr><td><code>responder_id_mismatch</code></td><td>ResponderID matches no candidate signer</td></tr><tr><td><code>responder_revocation_unknown</code></td><td>Delegated responder revocation status undetermined</td></tr><tr><td><code>responder_revoked</code></td><td>Delegated responder certificate is revoked</td></tr><tr><td><code>response_status_invalid</code></td><td>OCSPResponse status is not <code>successful</code></td></tr><tr><td><code>signature_invalid</code></td><td>Response signature fails</td></tr><tr><td><code>stale_response</code></td><td>Response outside its freshness window</td></tr><tr><td><code>unsupported</code></td><td>A response, request or certificate holds a value micro509 does not decode, see <code>ParseOcspResponseErrorCode</code></td></tr></tbody></table><h3 id="checkcertificaterevocationerrorcode" tabindex="-1">CheckCertificateRevocationErrorCode <a class="header-anchor" href="#checkcertificaterevocationerrorcode" aria-label="Permalink to “CheckCertificateRevocationErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>limit_exceeded</code></td><td>The certificate exceeds a micro509 decoding limit, see <code>ParseCertificateErrorCode</code></td></tr><tr><td><code>revocation_evidence_missing</code></td><td>No CRL or OCSP evidence was supplied</td></tr><tr><td><code>revocation_status_indeterminate</code></td><td>Evidence yielded no verdict under the hard-fail policy</td></tr><tr><td><code>unsupported</code></td><td>The certificate holds a value micro509 does not decode, see <code>ParseCertificateErrorCode</code></td></tr></tbody></table><h3 id="revocationindeterminatereasoncode" tabindex="-1">RevocationIndeterminateReasonCode <a class="header-anchor" href="#revocationindeterminatereasoncode" aria-label="Permalink to “RevocationIndeterminateReasonCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>certificate_status_missing</code></td><td>Response carries no entry for the certificate</td></tr><tr><td><code>certificate_status_unknown</code></td><td>Responder answered <code>unknown</code></td></tr><tr><td><code>crl_sign_not_permitted</code></td><td>CRL signer&#39;s keyUsage lacks <code>cRLSign</code>, or a v3 signer has no keyUsage</td></tr><tr><td><code>issuer_mismatch</code></td><td>Evidence issuer does not match the certificate&#39;s issuer</td></tr><tr><td><code>limit_exceeded</code></td><td>Evidence or a certificate it names exceeds a micro509 decoding limit</td></tr><tr><td><code>next_update_missing</code></td><td>OCSP response omits <code>nextUpdate</code> under <code>ocspProfile: &#39;rfc9919&#39;</code></td></tr><tr><td><code>non_applicable</code></td><td>No supplied CRL applies to the certificate</td></tr><tr><td><code>nonce_mismatch</code></td><td>Response nonce differs from the request&#39;s</td></tr><tr><td><code>ocsp_signing_missing</code></td><td>Delegated responder lacks the <code>ocspSigning</code> EKU</td></tr><tr><td><code>reason_code_unrecognized</code></td><td>Revoking evidence carries an unrecognized CRLReason under <code>unrecognizedReasonCode: &#39;reject&#39;</code></td></tr><tr><td><code>reason_coverage_incomplete</code></td><td>Applicable CRLs cover only some CRLReasons</td></tr><tr><td><code>request_mismatch</code></td><td>Response does not answer the supplied request</td></tr><tr><td><code>responder_chain_invalid</code></td><td>Responder certificate path fails validation</td></tr><tr><td><code>responder_id_mismatch</code></td><td>ResponderID matches no candidate signer</td></tr><tr><td><code>responder_revocation_unknown</code></td><td>Delegated responder revocation status undetermined</td></tr><tr><td><code>responder_revoked</code></td><td>Delegated responder certificate is revoked</td></tr><tr><td><code>response_status_invalid</code></td><td>OCSPResponse status is not <code>successful</code></td></tr><tr><td><code>signature_invalid</code></td><td>Evidence signature fails</td></tr><tr><td><code>stale_crl</code></td><td>CRL outside its <code>thisUpdate</code>/<code>nextUpdate</code> window or older than <code>crlMaxAgeMs</code></td></tr><tr><td><code>stale_response</code></td><td>Response outside its freshness window</td></tr><tr><td><code>unsupported</code></td><td>Evidence or a certificate it names holds a value micro509 does not decode</td></tr></tbody></table><p>The chain-level <code>RevocationIndeterminateReason</code> from <code>checkChainRevocation</code> and <code>verifyCertificateChain({ revocation })</code> uses its own names. A CRL that is outside its window or older than <code>crlMaxAgeMs</code> is reported as <code>crl_expired</code>, and an OCSP response without <code>nextUpdate</code> under <code>ocspProfile: &#39;rfc9919&#39;</code> as <code>ocsp_next_update_missing</code>. Evidence that revokes the certificate with an unrecognized CRLReason under <code>unrecognizedReasonCode: &#39;reject&#39;</code> is reported as <code>reason_code_unrecognized</code>, and as <code>crl_reason_code_unrecognized</code> or <code>ocsp_reason_code_unrecognized</code> at chain level. Either way, other evidence cannot settle the status as <code>good</code>.</p><h3 id="crlencodererrorcode" tabindex="-1">CrlEncoderErrorCode <a class="header-anchor" href="#crlencodererrorcode" aria-label="Permalink to “CrlEncoderErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>crl_number_invalid</code></td><td><code>crlNumber</code> or <code>baseCrlNumber</code> is negative, not an integer, or over 20 octets (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-5.2.3" target="_blank" rel="noreferrer">RFC 5280 §5.2.3</a>)</td></tr><tr><td><code>distribution_point_full_name_empty</code></td><td>IDP <code>fullName</code> present but holds no GeneralName</td></tr><tr><td><code>issuer_certificate_invalid</code></td><td><code>issuerCertificate</code> is not a PEM, DER or parsed certificate</td></tr><tr><td><code>issuer_distinguished_name_empty</code></td><td><a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-5.1.2.3" target="_blank" rel="noreferrer">RFC 5280 §5.1.2.3</a> requires a non-empty issuer DN</td></tr><tr><td><code>invalid_date</code></td><td>A CRL or revoked-entry date is an invalid <code>Date</code></td></tr><tr><td><code>next_update_not_after_this_update</code></td><td><code>nextUpdate</code> does not encode a later second than <code>thisUpdate</code></td></tr></tbody></table><h3 id="ocspencodererrorcode" tabindex="-1">OcspEncoderErrorCode <a class="header-anchor" href="#ocspencodererrorcode" aria-label="Permalink to “OcspEncoderErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid_date</code></td><td>A response date is an invalid <code>Date</code></td></tr><tr><td><code>invalid_revocation_reason_code</code></td><td><code>revocationReasonCode</code> is negative or not an integer</td></tr><tr><td><code>signer_certificate_key_mismatch</code></td><td>Signer certificate&#39;s SPKI does not match the signing key</td></tr></tbody></table><h2 id="micro509-keys" tabindex="-1">micro509/keys <a class="header-anchor" href="#micro509-keys" aria-label="Permalink to “micro509/keys”">​</a></h2><h3 id="importkeyerrorcode" tabindex="-1">ImportKeyErrorCode <a class="header-anchor" href="#importkeyerrorcode" aria-label="Permalink to “ImportKeyErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>limit_exceeded</code></td><td>A micro509 limit: an OBJECT IDENTIFIER sub-identifier encoded in more than 64 octets, a tag number of 2^53 or more, or DER nested deeper than 64 levels</td></tr><tr><td><code>malformed</code></td><td>Key material fails to parse or match the request</td></tr></tbody></table><h3 id="importencryptedkeyerrorcode" tabindex="-1">ImportEncryptedKeyErrorCode <a class="header-anchor" href="#importencryptedkeyerrorcode" aria-label="Permalink to “ImportEncryptedKeyErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid_password</code></td><td>Decryption failed, or plaintext is not a private key</td></tr><tr><td><code>kdf_iterations_exceeded</code></td><td>PBKDF2 iteration count exceeds <code>maxKdfIterations</code> (2,000,000 default)</td></tr><tr><td><code>limit_exceeded</code></td><td>A micro509 limit: an OBJECT IDENTIFIER sub-identifier encoded in more than 64 octets, a tag number of 2^53 or more, or DER nested deeper than 64 levels</td></tr><tr><td><code>malformed</code></td><td>Envelope fails to parse before any decryption, including a PBKDF2 <code>iterationCount</code> outside 1 to 4294967295 whatever <code>maxKdfIterations</code> allows</td></tr></tbody></table><h3 id="encryptrsaoaeperrorcode" tabindex="-1">EncryptRsaOaepErrorCode <a class="header-anchor" href="#encryptrsaoaeperrorcode" aria-label="Permalink to “EncryptRsaOaepErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid_key</code></td><td>Key is not an RSA-OAEP public key with <code>encrypt</code> usage</td></tr><tr><td><code>message_too_long</code></td><td>Plaintext exceeds the OAEP capacity of the key</td></tr></tbody></table><h3 id="decryptrsaoaeperrorcode" tabindex="-1">DecryptRsaOaepErrorCode <a class="header-anchor" href="#decryptrsaoaeperrorcode" aria-label="Permalink to “DecryptRsaOaepErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>decryption_failed</code></td><td>Deliberately opaque: wrong key, wrong label, or bad ciphertext</td></tr><tr><td><code>invalid_key</code></td><td>Key is not an RSA-OAEP private key with <code>decrypt</code> usage</td></tr></tbody></table><h2 id="micro509-pem" tabindex="-1">micro509/pem <a class="header-anchor" href="#micro509-pem" aria-label="Permalink to “micro509/pem”">​</a></h2><h3 id="pemerrorcode" tabindex="-1">PemErrorCode <a class="header-anchor" href="#pemerrorcode" aria-label="Permalink to “PemErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>malformed</code></td><td>Encapsulation or base64 violates <a href="https://www.rfc-editor.org/rfc/rfc7468.html" target="_blank" rel="noreferrer">RFC 7468</a> strict mode</td></tr></tbody></table><h2 id="micro509-der" tabindex="-1">micro509/der <a class="header-anchor" href="#micro509-der" aria-label="Permalink to “micro509/der”">​</a></h2><h3 id="decodedererrorcode" tabindex="-1">DecodeDerErrorCode <a class="header-anchor" href="#decodedererrorcode" aria-label="Permalink to “DecodeDerErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>limit_exceeded</code></td><td>A micro509 limit: an OBJECT IDENTIFIER sub-identifier encoded in more than 64 octets, a tag number of 2^53 or more, or DER nested deeper than 64 levels</td></tr><tr><td><code>malformed</code></td><td>Bytes are not the expected DER structure</td></tr><tr><td><code>unsupported</code></td><td>A TeletexString holds an octet outside the X.690 §8.23.5.2 initial state, which micro509 does not decode</td></tr></tbody></table><h2 id="micro509-pkcs" tabindex="-1">micro509/pkcs <a class="header-anchor" href="#micro509-pkcs" aria-label="Permalink to “micro509/pkcs”">​</a></h2><h3 id="parsepfxerrorcode" tabindex="-1">ParsePfxErrorCode <a class="header-anchor" href="#parsepfxerrorcode" aria-label="Permalink to “ParsePfxErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid_password</code></td><td>MAC or decryption rejects the supplied password</td></tr><tr><td><code>kdf_iterations_exceeded</code></td><td>The PBES2 bags&#39; combined PBKDF2 iteration counts exceed <code>maxKdfIterations</code> (2,000,000 default), or the MAC&#39;s count exceeds its own <code>maxKdfIterations</code> (100,000 default for the PKCS#12 KDF, 2,000,000 for PBMAC1)</td></tr><tr><td><code>limit_exceeded</code></td><td>A micro509 limit: an OBJECT IDENTIFIER sub-identifier encoded in more than 64 octets, a tag number of 2^53 or more, or DER or BER nested deeper than 64 levels</td></tr><tr><td><code>malformed</code></td><td>PFX structure fails to parse, including a PBKDF2 <code>iterationCount</code> outside 1 to 4294967295 in a PBES2 bag or a PBMAC1 MAC</td></tr><tr><td><code>password_not_bmp_string</code></td><td>The <a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">RFC 7292</a> MAC password (<code>macPassword</code>, or <code>password</code> as fallback) contains a UTF-16 surrogate, U+FFFE or U+FFFF</td></tr><tr><td><code>password_not_utf8</code></td><td>The PBMAC1 password contains an unpaired UTF-16 surrogate</td></tr><tr><td><code>password_required</code></td><td>Encrypted content present but no password given</td></tr><tr><td><code>unsupported</code></td><td>A certBag certificate&#39;s TeletexString name value holds an octet outside the X.690 §8.23.5.2 initial state, which micro509 does not decode</td></tr><tr><td><code>unsupported_mac_algorithm</code></td><td>The MAC is neither the SHA-256 <a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">RFC 7292</a> MAC nor a supported PBMAC1 variant</td></tr><tr><td><code>weak_mac_key_length</code></td><td>PBMAC1 PBKDF2 <code>keyLength</code> is below 20 octets</td></tr></tbody></table><h3 id="createpfxerrorcode" tabindex="-1">CreatePfxErrorCode <a class="header-anchor" href="#createpfxerrorcode" aria-label="Permalink to “CreatePfxErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid_certificate</code></td><td>A certificate source fails to parse</td></tr></tbody></table><h3 id="pfxencodererrorcode" tabindex="-1">PfxEncoderErrorCode <a class="header-anchor" href="#pfxencodererrorcode" aria-label="Permalink to “PfxEncoderErrorCode”">​</a></h3><p><code>createPfx</code> throws this as a <code>ResultError</code>.</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid_friendly_name</code></td><td>A bag <code>friendlyName</code> is not a BMPString of 1 to 255 characters (<a href="https://www.rfc-editor.org/rfc/rfc2985.html#page-17" target="_blank" rel="noreferrer">RFC 2985 §5.5.1</a>)</td></tr></tbody></table><h3 id="createpkcs12macdataerrorcode" tabindex="-1">CreatePkcs12MacDataErrorCode <a class="header-anchor" href="#createpkcs12macdataerrorcode" aria-label="Permalink to “CreatePkcs12MacDataErrorCode”">​</a></h3><p><code>createPkcs12MacData</code>, and <code>createPfx</code> through its <code>mac</code> option, throw these as a <code>ResultError</code>.</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid_iterations</code></td><td><code>iterations</code> is not a positive safe integer (<a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">RFC 7292</a> MAC) or not an integer from 1 to 4294967295 (PBMAC1)</td></tr><tr><td><code>password_not_bmp_string</code></td><td><a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">RFC 7292</a> MAC password contains a UTF-16 surrogate, U+FFFE or U+FFFF</td></tr><tr><td><code>password_not_utf8</code></td><td>PBMAC1 password contains an unpaired UTF-16 surrogate</td></tr></tbody></table><h3 id="parsepkcs12macdataerrorcode" tabindex="-1">ParsePkcs12MacDataErrorCode <a class="header-anchor" href="#parsepkcs12macdataerrorcode" aria-label="Permalink to “ParsePkcs12MacDataErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>kdf_iterations_exceeded</code></td><td>With a password, the iteration count exceeds <code>maxKdfIterations</code> (100,000 default for the PKCS#12 KDF, 2,000,000 for PBMAC1), or an <a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">RFC 7292</a> MAC count exceeds <code>Number.MAX_SAFE_INTEGER</code></td></tr><tr><td><code>limit_exceeded</code></td><td>A micro509 limit: an OBJECT IDENTIFIER sub-identifier encoded in more than 64 octets, a tag number of 2^53 or more, or DER nested deeper than 64 levels</td></tr><tr><td><code>malformed</code></td><td>MacData structure fails to parse, an iteration count is below 1, a PBMAC1 count exceeds 4294967295 whatever <code>maxKdfIterations</code> allows, or, without a password, an <a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">RFC 7292</a> MAC count exceeds <code>Number.MAX_SAFE_INTEGER</code></td></tr><tr><td><code>password_not_bmp_string</code></td><td><a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">RFC 7292</a> MAC password contains a UTF-16 surrogate, U+FFFE or U+FFFF</td></tr><tr><td><code>password_not_utf8</code></td><td>PBMAC1 password contains an unpaired UTF-16 surrogate</td></tr><tr><td><code>unsupported_mac_algorithm</code></td><td>The MAC is neither the SHA-256 <a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">RFC 7292</a> MAC nor a supported PBMAC1 variant</td></tr><tr><td><code>weak_mac_key_length</code></td><td>PBMAC1 PBKDF2 <code>keyLength</code> is below 20 octets</td></tr></tbody></table><p>Without a password no key is derived. <code>maxKdfIterations</code> is not applied, and <code>verification</code> is <code>&#39;unchecked&#39;</code> for any <a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">RFC 7292</a> MAC count from 1 to <code>Number.MAX_SAFE_INTEGER</code> and any PBMAC1 count from 1 to 4294967295.</p><h3 id="parsepkcs7errorcode" tabindex="-1">ParsePkcs7ErrorCode <a class="header-anchor" href="#parsepkcs7errorcode" aria-label="Permalink to “ParsePkcs7ErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>limit_exceeded</code></td><td>A micro509 limit: an OBJECT IDENTIFIER sub-identifier encoded in more than 64 octets, a tag number of 2^53 or more, or DER nested deeper than 64 levels</td></tr><tr><td><code>malformed</code></td><td>ContentInfo or SignedData fails to parse</td></tr><tr><td><code>not_signed_data</code></td><td>ContentInfo carries a content type other than data</td></tr><tr><td><code>unsupported</code></td><td>A signer issuer TeletexString value holds an octet outside the X.690 §8.23.5.2 initial state, which micro509 does not decode</td></tr></tbody></table><h3 id="createpkcs7certbagerrorcode" tabindex="-1">CreatePkcs7CertBagErrorCode <a class="header-anchor" href="#createpkcs7certbagerrorcode" aria-label="Permalink to “CreatePkcs7CertBagErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid_certificate</code></td><td>A certificate source fails to parse</td></tr><tr><td><code>limit_exceeded</code></td><td>A certificate exceeds a micro509 decoding limit, see <code>ParseCertificateErrorCode</code></td></tr><tr><td><code>unsupported</code></td><td>A certificate holds a value micro509 does not decode, see <code>ParseCertificateErrorCode</code></td></tr></tbody></table><h3 id="createpkcs7signeddataerrorcode" tabindex="-1">CreatePkcs7SignedDataErrorCode <a class="header-anchor" href="#createpkcs7signeddataerrorcode" aria-label="Permalink to “CreatePkcs7SignedDataErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>invalid_certificate</code></td><td>An <code>additionalCertificates</code> entry fails to parse</td></tr><tr><td><code>invalid_signer_certificate</code></td><td>A signer&#39;s certificate source fails to parse</td></tr><tr><td><code>limit_exceeded</code></td><td>A signer or additional certificate exceeds a micro509 decoding limit, see <code>ParseCertificateErrorCode</code></td></tr><tr><td><code>no_signers</code></td><td><code>signers</code> is empty</td></tr><tr><td><code>signer_certificate_key_mismatch</code></td><td>Signer certificate&#39;s SPKI does not match the signing key</td></tr><tr><td><code>unsupported_signer_key</code></td><td>Signing key algorithm has no CMS digest mapping</td></tr><tr><td><code>unsupported</code></td><td>A signer or additional certificate holds a value micro509 does not decode, see <code>ParseCertificateErrorCode</code></td></tr></tbody></table><h3 id="verifypkcs7signeddataerrorcode" tabindex="-1">VerifyPkcs7SignedDataErrorCode <a class="header-anchor" href="#verifypkcs7signeddataerrorcode" aria-label="Permalink to “VerifyPkcs7SignedDataErrorCode”">​</a></h3><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>detached_content_required</code></td><td>SignedData has no <code>eContent</code> and no <code>content</code> option supplied</td></tr><tr><td><code>limit_exceeded</code></td><td>A micro509 limit while parsing, see <code>ParsePkcs7ErrorCode</code></td></tr><tr><td><code>malformed</code></td><td>Structure, attributes, or algorithms fail to process</td></tr><tr><td><code>message_digest_mismatch</code></td><td>Content digest differs from the <code>messageDigest</code> attribute</td></tr><tr><td><code>no_signers</code></td><td><code>signerInfos</code> is empty</td></tr><tr><td><code>not_signed_data</code></td><td>ContentInfo carries a content type other than SignedData</td></tr><tr><td><code>signature_invalid</code></td><td>A signer&#39;s signature does not verify</td></tr><tr><td><code>signer_not_found</code></td><td>No embedded certificate matches a SignerInfo</td></tr><tr><td><code>unsupported</code></td><td>A signer issuer value micro509 does not decode, see <code>ParsePkcs7ErrorCode</code></td></tr></tbody></table>`,81)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};